//! WebAuthn verification against real authenticator vectors (Phase 0, B3).
//!
//! The vectors in `golden/presence/` are the W3C WebAuthn Level 3 test
//! vectors (section 16): registration and authentication ceremonies for
//! ES256 (no attestation, packed, Apple anonymous) and EdDSA (packed), made
//! with real key material for RP `example.org`. They were generated by the
//! spec authors with HKDF-derived keys and RFC 6979 nonces; nothing here was
//! produced by Ligus's own code. Their authenticators didn't always set UV,
//! so they're checked with a policy for `example.org` without the UV
//! requirement; Ligus's production policy (RP `ligus.ai`, UV required) is
//! covered by the reject cases below and the fold tests in hive-runtime.

use hive_core::presence::{self, b64url, verify_create, verify_get, PasskeyKey, PresenceAssertion, Policy};

struct Vector {
    reg_challenge: Vec<u8>,
    credential_id: Vec<u8>,
    reg_client_data: Vec<u8>,
    attestation: Vec<u8>,
    auth_challenge: Vec<u8>,
    auth_data: Vec<u8>,
    auth_client_data: Vec<u8>,
    signature: Vec<u8>,
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn load(name: &str) -> Vector {
    let path = format!("{}/tests/golden/presence/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let v: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let r = |k: &str| unhex(v["registration"][k].as_str().unwrap());
    let a = |k: &str| unhex(v["authentication"][k].as_str().unwrap());
    Vector {
        reg_challenge: r("challenge"),
        credential_id: r("credential_id"),
        reg_client_data: r("clientDataJSON"),
        attestation: r("attestationObject"),
        auth_challenge: a("challenge"),
        auth_data: a("authenticatorData"),
        auth_client_data: a("clientDataJSON"),
        signature: a("signature"),
    }
}

const ORIGINS: &[&str] = &["https://example.org"];
fn policy() -> Policy<'static> {
    Policy { rp_id: "example.org", origins: ORIGINS, require_uv: false }
}

impl Vector {
    fn create(&self) -> PresenceAssertion {
        PresenceAssertion {
            credential_id: b64url(&self.credential_id),
            authenticator_data: b64url(&self.attestation),
            client_data_json: b64url(&self.reg_client_data),
            signature: String::new(),
        }
    }
    fn get(&self) -> PresenceAssertion {
        PresenceAssertion {
            credential_id: b64url(&self.credential_id),
            authenticator_data: b64url(&self.auth_data),
            client_data_json: b64url(&self.auth_client_data),
            signature: b64url(&self.signature),
        }
    }
    /// Register, then authenticate with the registered key.
    fn run(&self, want_alg: i32) -> PasskeyKey {
        let (id, alg, pk) = verify_create(&self.create(), &self.reg_challenge, &policy()).expect("registration verifies");
        assert_eq!((id, alg), (self.credential_id.clone(), want_alg));
        let key = PasskeyKey { alg, public_key: pk, recovery: false };
        verify_get(&self.get(), &key, &self.auth_challenge, &policy()).expect("assertion verifies");
        key
    }
}

fn tampered(a: &PresenceAssertion, field: usize, at: usize) -> PresenceAssertion {
    let mut a = a.clone();
    let slot = match field {
        0 => &mut a.authenticator_data,
        1 => &mut a.client_data_json,
        _ => &mut a.signature,
    };
    let mut bytes = presence::unb64url(slot).unwrap();
    let i = at % bytes.len();
    bytes[i] ^= 0x01;
    *slot = b64url(&bytes);
    a
}

fn rejects_tampering(v: &Vector, key: &PasskeyKey) {
    let good = v.get();
    for field in 0..3 {
        for at in [0usize, 7, 31, 33, 40, 63, 64, 100] {
            assert!(
                verify_get(&tampered(&good, field, at), key, &v.auth_challenge, &policy()).is_err(),
                "a flipped bit in field {field} at {at} must not verify"
            );
        }
    }
    let mut other = v.auth_challenge.clone();
    other[0] ^= 1;
    assert!(verify_get(&good, key, &other, &policy()).is_err(), "wrong challenge");
    let wrong_rp = Policy { rp_id: "ligus.ai", ..policy() };
    assert!(verify_get(&good, key, &v.auth_challenge, &wrong_rp).is_err(), "wrong RP id");
    let wrong_origin = Policy { origins: &["https://ligus.ai"], ..policy() };
    assert!(verify_get(&good, key, &v.auth_challenge, &wrong_origin).is_err(), "wrong origin");
    // A registration's client data is not an assertion's.
    let swapped = PresenceAssertion { client_data_json: b64url(&v.reg_client_data), ..good.clone() };
    assert!(verify_get(&swapped, key, &v.reg_challenge, &policy()).is_err(), "webauthn.create isn't webauthn.get");
}

#[test]
fn presence_vectors_es256() {
    for name in ["none-es256", "packed-es256", "apple-es256"] {
        let v = load(name);
        let key = v.run(presence::ES256);
        assert_eq!(key.public_key.len(), 65);
        rejects_tampering(&v, &key);
    }
}

#[test]
fn presence_vectors_eddsa() {
    let v = load("packed-eddsa");
    let key = v.run(presence::EDDSA);
    assert_eq!(key.public_key.len(), 32);
    rejects_tampering(&v, &key);
}

#[test]
fn presence_requires_uv() {
    // The vectors' authenticators didn't set UV: Ligus's policy refuses them.
    let v = load("none-es256");
    let key = v.run(presence::ES256);
    let strict = Policy { require_uv: true, ..policy() };
    let err = verify_get(&v.get(), &key, &v.auth_challenge, &strict).unwrap_err();
    assert!(err.0.contains("UV"), "{err}");
}

#[test]
fn presence_rejects_wrong_rpid() {
    let v = load("packed-eddsa");
    let key = v.run(presence::EDDSA);
    assert!(verify_get(&v.get(), &key, &v.auth_challenge, &Policy::ligus()).is_err());
    assert!(verify_create(&v.create(), &v.reg_challenge, &Policy { rp_id: "example.com", ..policy() }).is_err());
}

#[test]
fn a_key_from_one_vector_never_verifies_another() {
    let a = load("none-es256");
    let b = load("apple-es256");
    let ka = a.run(presence::ES256);
    assert!(verify_get(&b.get(), &ka, &b.auth_challenge, &policy()).is_err());
}

#[test]
fn malformed_attestation_objects_are_refused_not_panicked() {
    let v = load("none-es256");
    for cut in [0usize, 1, 5, 20, 60, 100, v.attestation.len() - 1] {
        let mut a = v.create();
        a.authenticator_data = b64url(&v.attestation[..cut]);
        assert!(verify_create(&a, &v.reg_challenge, &policy()).is_err());
    }
    let mut deep = vec![0x81u8; 64]; // arrays nested 64 deep
    deep.push(0x00);
    assert!(presence::cbor_decode(&deep).is_err());
    assert!(presence::cbor_decode(&[0x5b, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]).is_err(), "a huge length");
}
